/**
 * Issue #43 - README "select auto-selection": the <option> whose value matches the bound value gets `selected`.
 * This must also hold for options generated by data-t-list inside the <select> (not only static options).
 * Covered in SSR (renderer) and CSR (jsdom), through the same helpers.
 */
import { describe, test, afterEach } from 'node:test';
import assert from 'node:assert';
import { render, csr, cleanupAll } from './helpers.cjs';

const pending_cleanup = [];
afterEach(() => { cleanupAll(); while (pending_cleanup.length) pending_cleanup.pop()(); });

const link = (name, href) => `<link data-t-source="${name}" href="_sys/data/${href}">`;
const HEAD = link('bk', 'books.json?id=1&_limit=1') + link('cats', 'categories.json');
const CATS = [{ id: 1, name: 'Fiction' }, { id: 2, name: 'Science' }, { id: 3, name: 'History' }];
const sources = (category_id) => ({ books: [{ id: 1, title: 'Atlas', category_id }], categories: CATS });

const STATIC_SEL = '<select id="s1" name="category_id"><option value="1">a</option><option value="2">b</option></select>';
const LIST_SEL = '<select id="s2" name="category_id"><option data-t-list="cats" value="{cats.id}">{cats.name}</option></select>';
const FORM = (inner) => `<form data-t-scope="bk">${inner}</form>`;

// Values of the options carrying a `selected` attribute (what a browser / the saved form relies on)
const selectedValues = (doc, sel) => [...doc.querySelector(sel).querySelectorAll('option')].filter(o => o.hasAttribute('selected')).map(o => o.value);
const optionValues = (doc, sel) => [...doc.querySelector(sel).querySelectorAll('option')].map(o => o.value);

for (const mode of ['ssr', 'csr']) {
    const r = (body, cid, o = {}) => render(mode, body, { head: HEAD, sources: sources(cid), ...o });

    describe(`${mode.toUpperCase()}: <select> with data-t-list options (#43)`, () => {
        test('(1) issue repro: static select is selected (guard), list-generated select is selected too', async () => {
            const doc = await r(FORM(STATIC_SEL + LIST_SEL), 1);
            assert.deepStrictEqual(selectedValues(doc, '#s1'), ['1']);
            assert.deepStrictEqual(optionValues(doc, '#s2'), ['1', '2', '3']);
            assert.deepStrictEqual(selectedValues(doc, '#s2'), ['1']);
        });
        test('(2) value matching a later option selects only that option', async () => {
            const doc = await r(FORM(LIST_SEL), 2);
            assert.deepStrictEqual(selectedValues(doc, '#s2'), ['2']);
            const doc3 = await r(FORM(LIST_SEL), 3);
            assert.deepStrictEqual(selectedValues(doc3, '#s2'), ['3']);
        });
        test('(3) value matching no option selects nothing and does not crash', async () => {
            const doc = await r(FORM(LIST_SEL), 99);
            assert.deepStrictEqual(optionValues(doc, '#s2'), ['1', '2', '3']);
            assert.deepStrictEqual(selectedValues(doc, '#s2'), []);
        });
        test('(4) number bound value vs string option values', async () => {
            const doc = await r(FORM(STATIC_SEL + LIST_SEL), 2); // stored as the number 2, option values are "2"
            assert.deepStrictEqual(selectedValues(doc, '#s1'), ['2']);
            assert.deepStrictEqual(selectedValues(doc, '#s2'), ['2']);
        });
        test('(4) string bound value vs numeric-looking option values', async () => {
            const doc = await r(FORM(LIST_SEL), '2');
            assert.deepStrictEqual(selectedValues(doc, '#s2'), ['2']);
        });
        test('(5) scope-less select filled from _sys.query (#47) selects the list option', async () => {
            const doc = await render(mode, STATIC_SEL + LIST_SEL, { head: link('cats', 'categories.json'), sources: { categories: CATS }, query: { category_id: '2' } });
            assert.deepStrictEqual(selectedValues(doc, '#s1'), ['2']);
            assert.deepStrictEqual(selectedValues(doc, '#s2'), ['2']);
        });
        test('(7) form state: select.value equals the bound value', async () => {
            const doc = await r(FORM(STATIC_SEL + LIST_SEL), 2);
            assert.strictEqual(doc.querySelector('#s1').value, '2');
            assert.strictEqual(doc.querySelector('#s2').value, '2');
        });
        test('(7) no match: no option is marked selected via the attribute even with a valid first option', async () => {
            const doc = await r(FORM(LIST_SEL), 99);
            assert.strictEqual(doc.querySelectorAll('#s2 option[selected]').length, 0);
        });
    });
}

// (6) <select multiple> is not defined in the README: skipped.

describe('select list options: SSR output re-booted in CSR (hydration, #43)', () => {
    test('(8) the selection set by SSR is kept after CSR hydration', async () => {
        const body = FORM(STATIC_SEL + LIST_SEL);
        const src = sources(2);
        const ssrDoc = await render('ssr', body, { head: HEAD, sources: src });
        const html = '<!DOCTYPE html>' + ssrDoc.documentElement.outerHTML;
        const files = { '_sys/data/books.json': src.books, '_sys/data/categories.json': src.categories };
        const c = await csr(html, { url: 'http://localhost/page.html', files });
        pending_cleanup.push(c.cleanup);
        const d = c.document;
        assert.deepStrictEqual(selectedValues(d, '#s1'), ['2']);
        assert.deepStrictEqual(selectedValues(d, '#s2'), ['2']);
        assert.strictEqual(d.querySelector('#s2').value, '2');
    });
});
